-- ФИНАЛЬНЫЙ ПРАВИЛЬНЫЙ SQL (100% под вашу БД)
-- Тесты 21 и 22 из testing.kg

-- 1. СОЗДАТЬ ТЕСТЫ
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title;

-- 2. ТЕСТ 21 - 30 вопросов (формат: A vs B)
-- ВАЖНО: correct_option - это ЧИСЛО (0=A, 1=B)

-- 3. ТЕСТ 22 - ЧАСТЬ 2 (30 вопросов)
-- ВАЖНО: correct_option - это индекс в массиве (0=A, 1=B, 2=C, 3=D, 4=E)

-- ПРОВЕРКА
SELECT 
  t.title_ru as "Тест",
  COUNT(q.id) as "Вопросов",
  COUNT(CASE WHEN q.correct_option IS NOT NULL THEN 1 END) as "С ответами"
FROM tests t
LEFT JOIN questions q ON t.id = q.test_id
WHERE t.id IN ('21212121-2121-2121-2121-212121212121', '22222222-2222-2222-2222-222222222222')
GROUP BY t.title_ru;
